def is_valid_parenthese(s: str) -> bool:
    """
    Return True if the string s contains a valid sequence of parentheses,
    otherwise return False. Valid characters are '(', ')', '{', '}', '[' and ']'.
    """
    stack = []
    pairs = {')': '(', '}': '{', ']': '['}
    opening = set(pairs.values())

    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
        else:
            # ignore any other characters
            continue

    return not stack
```

