import math

def sum_div(n: int) -> int:
    """Return the sum of all proper divisors of n (excluding n itself)."""
    if n <= 1:
        return 0

    total = 0
    limit = math.isqrt(n)
    for i in range(1, limit + 1):
        if n % i == 0:
            # i is a divisor
            if i < n:
                total += i
            # paired divisor
            j = n // i
            if j != i and j < n:
                total += j
    return total
```

