def max_occurrences(lst):
    """
    Return the element(s) that occur most frequently in `lst`.
    If a single element has the maximum count, return that element.
    If multiple elements tie, return a tuple of those elements in the order
    of their first appearance in the list.
    """
    if not lst:
        return None  # or raise ValueError("Empty list")

    # Count occurrences
    counts = {}
    for item in lst:
        counts[item] = counts.get(item, 0) + 1

    # Find maximum count
    max_count = max(counts.values())

    # Collect items with max count, preserving order of first appearance
    seen = set()
    result = []
    for item in lst:
        if counts[item] == max_count and item not in seen:
            seen.add(item)
            result.append(item)

    # Return single element or tuple
    return result[0] if len(result) == 1 else tuple(result)
```

