import math

def answer(a: int, b: int):
    """
    Find two distinct positive integers x and y such that
    lcm(x, y) lies within the inclusive range [a, b].
    Returns a tuple (x, y). If no such pair exists, returns None.
    """
    # Search for the smallest pair in lexicographic order
    for x in range(1, b + 1):
        for y in range(x + 1, b + 1):
            l = x * y // math.gcd(x, y)
            if a <= l <= b:
                return (x, y)
    return None
