def assign_freq(tuples_list):
    """
    Assigns frequency counts to each unique tuple in the input list.
    The order of tuples in the output matches the order of their first appearance.
    Returns a string representation of the resulting list of tuples.
    """
    freq = {}
    order = []
    for t in tuples_list:
        if t not in freq:
            freq[t] = 1
