def Find_Min(lists):
    """
    Return the sublist with the minimum length from a list of lists.
    If multiple sublists have the same minimum length, the first one is returned.
    """
    if not lists:
        return None  # or raise ValueError("Input list is empty")

    min_sub = lists[0]
    min_len = len(min_sub)

    for sub in lists[1:]:
        if len(sub) < min_len:
            min_len = len(sub)
            min_sub = sub

    return min_sub
