def areEquivalent(a: int, b: int) -> bool:
    """
    Return True if the sum of proper divisors of a equals that of b.
    Proper divisors are all positive divisors less than the number itself.
    """
    def sum_proper_divisors(n: int) -> int:
        if n <= 1:
            return 0
        total = 1  # 1 is always a proper divisor for n > 1
        limit = int(n**0.5)
        for d in range(2, limit + 1):
            if n % d == 0:
                total += d
                other = n // d
                if other != d and other != n:
                    total += other
        return total

    return sum_proper_divisors(a) == sum_proper_divisors(b)
```

