def maximum_segments(n, a, b, c):
    # dp[i] will hold the maximum number of segments that sum to i
    dp = [-1] * (n + 1)
    dp[0] = 0

    for i in range(1, n + 1):
        best = -1
        if i - a >= 0 and dp[i - a] != -1:
            best = max(best, dp[i - a] + 1)
        if i - b >= 0 and dp[i - b] != -1:
            best = max(best, dp[i - b] + 1)
        if i - c >= 0 and dp[i - c] != -1:
            best = max(best, dp[i - c] + 1)
        dp[i] = best

    return dp[n] if dp[n] != -1 else 0
