def find_rotation_count(arr):
    n = len(arr)
    if n == 0:
        return 0
    low, high = 0, n - 1
    while low <= high:
        # If the current subarray is sorted, the minimum is at low
        if arr[low] <= arr[high]:
            return low
        mid = (low + high) // 2
        next_idx = (mid + 1) % n
        prev_idx = (mid - 1 + n) % n
        # Check if mid is the minimum element
        if arr[mid] <= arr[next_idx] and arr[mid] <= arr[prev_idx]:
            return mid
        # Decide which half to search
        if arr[mid] <= arr[high]:
            high = mid - 1
        else:
            low = mid + 1
    return 0
```

