def max_profit(prices, k):
    n = len(prices)
    if k == 0 or n < 2:
        return 0
    # If k is large enough, it's equivalent to unlimited transactions
    if k >= n // 2:
        profit = 0
        for i in range(1, n):
            if prices[i] > prices[i - 1]:
                profit += prices[i] - prices[i - 1]
        return profit

    # DP arrays: buy[j] = max profit after j-th buy, sell[j] = max profit after j-th sell
    buy = [-float('inf')] * (k + 1)
    sell = [0] * (k + 1)

    for price in prices:
        for j in range(1, k + 1):
            buy[j] = max(buy[j], sell[j - 1] - price)
            sell[j] = max(sell[j], buy[j] + price)

    return sell[k]
