def binomial_Coeff(n, k):
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    k = min(k, n - k)  # Take advantage of symmetry
    res = 1
    for i in range(1, k + 1):
        res = res * (n - k + i) // i
    return res
