def breakSum(n):
    memo = {}

    def helper(x):
        if x == 0:
            return 0
        if x in memo:
            return memo[x]
        # Option 1: keep x as is
        # Option 2: break into x//2, x//3, x//4 and sum their maximum values
        broken_sum = helper(x // 2) + helper(x // 3) + helper(x // 4)
        result = max(x, broken_sum)
        memo[x] = result
        return result

    return helper(n)

# Test cases
assert breakSum(12) == 13
assert breakSum(24) == 27
assert breakSum(23) == 23
