def magic_square_test(matrix):
    # Check if matrix is square
    n = len(matrix)
    if n == 0:
        return False
    for row in matrix:
        if len(row) != n:
            return False

    # Check all numbers are distinct and exactly 1 to n^2
    numbers = []
    for row in matrix:
        numbers.extend(row)
    if set(numbers) != set(range(1, n * n + 1)):
        return False

    # Target sum (magic constant)
    target = sum(matrix[0])

    # Check rows
    for row in matrix:
        if sum(row) != target:
            return False

    # Check columns
    for j in range(n):
        col_sum = sum(matrix[i][j] for i in range(n))
        if col_sum != target:
            return False

    # Check main diagonal
    diag1 = sum(matrix[i][i] for i in range(n))
    if diag1 != target:
        return False

    # Check anti-diagonal
    diag2 = sum(matrix[i][n - 1 - i] for i in range(n))
    if diag2 != target:
        return False

    return True
```

