def get_max_sum(n):
    """
    Finds the maximum sum possible using the equation:
    f(n) = max( (f(n/2) + f(n/3) + f(n/4) + f(n/5)), n)
    The function assumes integer division for n/k.
    """
    if n == 0:
        return 0
    if n == 1:
        return 1  # Base case, though not explicitly defined, f(1) should be 1 based on the structure

    memo = {}

    def f(k):
        if k in memo:
            return memo[k]
        if k == 0:
            return 0
        if k == 1:
            return 1

        # Calculate the recursive sum
        # We use integer division as implied by the context of such problems
        recursive_sum = f(k // 2) + f(k // 3) + f(k // 4) + f(k // 5)

        # Apply the formula: f(n) = max(recursive_sum, n)
        result = max(recursive_sum, k)
        memo[k] = result
        return result

    return f(n)
```

