import math

def binomial_Coeff(n, k):
    """
    Calculates the binomial coefficient "n choose k".
    C(n, k) = n! / (k! * (n-k)!)
    """
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    if k > n // 2:
        k = n - k

    # Using math.comb for efficiency and correctness in Python 3.8+
    if hasattr(math, 'comb'):
        return math.comb(n, k)

    # Manual calculation using multiplication/division to avoid large factorials
    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)
    return result
