def sum_div(n):
    """
    Returns the sum of all proper divisors of a number n.
    Proper divisors are all divisors excluding the number itself.
    """
    if n <= 0:
        return 0
    if n == 1:
        return 0  # 1 has no proper divisors other than itself (which is excluded)

    sum_of_divisors = 1  # Start with 1, as 1 is always a proper divisor for n > 1
    i = 2
    while i * i <= n:
        if n % i == 0:
            sum_of_divisors += i
            j = n // i
            if j != i:
                sum_of_divisors += j
        i += 1

    return sum_of_divisors
