def magic_square_test(square):
    """
    Checks if a given square matrix is a magic square.
    A magic square is a square grid where the sum of numbers in each row, 
    each column, and both main diagonals are the same.
    """
    n = len(square)
    if n == 0:
        return True  # Or False, depending on definition for empty square, but tests imply non-empty

    # Check if it's a square matrix (all rows have length n)
    for row in square:
        if len(row) != n:
            return False

    # Calculate the expected magic constant (sum of the first row)
    magic_constant = sum(square[0])

    # 1. Check row sums
    for row in square:
        if sum(row) != magic_constant:
            return False

    # 2. Check column sums
    for j in range(n):
        col_sum = 0
        for i in range(n):
            col_sum += square[i][j]
        if col_sum != magic_constant:
            return False

    # 3. Check main diagonal sum (top-left to bottom-right)
    diag1_sum = 0
    for i in range(n):
        diag1_sum += square[i][i]
    if diag1_sum != magic_constant:
        return False

    # 4. Check anti-diagonal sum (top-right to bottom-left)
    diag2_sum = 0
    for i in range(n):
        diag2_sum += square[i][n - 1 - i]
    if diag2_sum != magic_constant:
        return False

    return True
```

