def nCr_mod_p(n, r, p):
    if r < 0 or r > n:
        return 0
    if r == 0 or r == n:
        return 1
    if r > n - r:
        r = n - r
    C = [0] * (r + 1)
    C[0] = 1
    for i in range(1, n + 1):
