def max_chain_length(arr, n):
    # The problem requires finding the longest chain, which implies sorting the pairs first
    # based on the second element (b) for the dynamic programming approach to work correctly.
    # If the input array is not sorted, the DP logic (j < i) is flawed for this problem.
    arr.sort(key=lambda p: p.b)

    mcl = [1 for i in range(n)]
    for i in range(n):
        for j in range(i):
            # A chain can be formed if arr[j].b < arr[i].a
            if arr[j].b < arr[i].a:
                mcl[i] = max(mcl[i], mcl[j] + 1)

    max_len = 0
    if n > 0:
        max_len = max(mcl)

    return max_len
