def binomial_coeffi(n, k):
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    if k > n // 2:
        k = n - k

    res = 1
    for i in range(k):
        res = res * (n - i) // (i + 1)
    return res

def rencontres_number(n, m):
    if m < 0 or m > n:
        return 0
    if m == 0:
        return 1

    # The n-th rencontres number (or the number of permutations with exactly m fixed points)
    # is given by D_n = n! * sum_{k=0}^n ((-1)^k / k!)
    # The number of permutations of n elements with exactly m fixed points is:
    # C(n, m) * D_{n-m}

    # We need a function for derangement D_k
    def derangement(k):
        if k == 0:
            return 1
        if k == 1:
            return 0
        # D_k = (k-1) * (D_{k-1} + D_{k-2})
        return (k - 1) * (derangement(k - 1) + derangement(k - 2))

    return binomial_coeffi(n, m) * derangement(n - m)
